import{_ as o,C as r,o as i,c as l,a6 as e,E as n}from"./chunks/framework.QQy01QNh.js";const s="/xi-kari-skill/handbook/images/feedback.svg",m=JSON.parse('{"title":"收到消息，为什么还不算有效反馈","description":"回执证明消息到达；有效反馈要看后续状态是否因此改变。","frontmatter":{"title":"收到消息，为什么还不算有效反馈","description":"回执证明消息到达；有效反馈要看后续状态是否因此改变。"},"headers":[],"relativePath":"concepts/feedback.md","filePath":"concepts/feedback.md"}'),c={name:"concepts/feedback.md"};function h(d,a,p,_,f,k){const t=r("FeedbackExplorer");return i(),l("div",null,[a[0]||(a[0]=e('<h1 id="收到消息-为什么还不算有效反馈" tabindex="-1">收到消息，为什么还不算有效反馈 <a class="header-anchor" href="#收到消息-为什么还不算有效反馈" aria-label="Permalink to &quot;收到消息，为什么还不算有效反馈&quot;">​</a></h1><p>申诉已经被接收，系统真的改变了吗？</p><p><strong>回执证明消息到达；有效反馈要看后续状态是否因此改变。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文设想一个收到申诉的虚拟制度。第一种情况是收件、发出回执，案件记录、规则、资源等却没有改变。这能确认消息到了，不能确认有效反馈。第二种情况是申诉经指定通道改变了案件状态字段：如果相对没有返回或通道被阻断的情形，确实出现可检测差异，就进入有效反馈的判断；但字段变化尚未进入执行，仍不能称为完整制度写回。</p><p>第三种情况才是字段变化进入实际执行，并能追踪执行和持续时间。读这个例子时，可以沿着“原来的状态—返回通道—接收位置—后续改变”看下去，而不只数有多少通知、记录和回复。即使后续状态变了，也还要另问改变是否有益、是否持续，以及是否形成了学习。</p><figure class="concept-figure"><img src="'+s+'" alt="一条申诉可以停在哪一步"><figcaption>箭头表示需要继续核对的关系，不表示收到申诉后必然逐级完成。</figcaption></figure><h2 id="改变条件-看看有什么不同" tabindex="-1">改变条件，看看有什么不同 <a class="header-anchor" href="#改变条件-看看有什么不同" aria-label="Permalink to &quot;改变条件，看看有什么不同&quot;">​</a></h2>',8)),n(t),a[1]||(a[1]=e('<h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>信号被接收、回执被生成、表达被记录或档案被保存，都只证明到达或留痕</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-03.html#section-3-3">§3.3 D2 有效反馈</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-4">§6.4 反馈、制度写回与学习的虚拟申诉例</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>这是原文虚拟申诉例，用于区分概念，不是现实制度的实证。有效反馈可以有害、失真或不稳定；不自动等于学习、正当性或修复。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./history.html">留下记录，与真正学会了什么</a></li><li><a href="./recovery.html">依靠支持恢复的功能，算不算真的恢复</a></li><li><a href="./../cases/toyota-andon.html">真实案例 · 丰田安灯：异常怎样进入处理流程</a></li></ul>',7))])}const b=o(c,[["render",h]]);export{m as __pageData,b as default};
